runmysteriet.handler.ShieldHandler.prototype.setFallbackWord=function(){if(this.m_levelNumber>=11)this.m_wordData={word:"warrior",Subword:["fighter","battle"]};else if(this.m_levelNumber>=6)this.m_wordData={word:"shield",Subword:["protection","battle"]};else this.m_wordData={word:"raven",Subword:["black bird","viking sign"]};this.m_word=String(this.m_wordData.word||"").toUpperCase();this.m_hints=this.m_wordData.Subword||[]};
