runmysteriet.handler.PlayerHandler.prototype.keepPlayersInsideLevel=function(){var i=0;var player=null;var maxX=0;if(!this.platformHandler||!this.platformHandler.levelWidth)return;for(i=0;i<this.players.length;i++){player=this.players[i];if(!player||player.isDead===true)continue;if(player.x<0)player.x=0;maxX=this.platformHandler.levelWidth-player.width;if(player.x>maxX)player.x=maxX}};
