runmysteriet.scene.TextInputView.prototype.updateText=function(){if(!this.m_nameInputs||this.m_nameInputs.length<2)return;if(this.m_player1Text){this.m_player1Text.text=this.formatPlayerRow(0);this.m_player1Text.center=this.application.screen.center;this.m_player1Text.y-=15}if(this.m_player2Text){this.m_player2Text.text=this.formatPlayerRow(1);this.m_player2Text.center=this.application.screen.center;this.m_player2Text.y+=20}if(this.m_letterText){this.m_letterText.text="SELECTED LETTER: "+this.m_nameInputs[this.m_currentPlayer].getSelectedLetter().toUpperCase();
this.m_letterText.center=this.application.screen.center;this.m_letterText.y+=60}if(this.m_startText){if(this.areBothNamesComplete())this.m_startText.text="PRESS ENTER/X TO START";else if(this.m_currentPlayer===0)this.m_startText.text="FILL IN PLAYER 1";else this.m_startText.text="FILL IN PLAYER 2";this.m_startText.center=this.application.screen.center;this.m_startText.y+=90}};
runmysteriet.scene.TextInputView.prototype.formatPlayerRow=function(index){var nameInput=this.m_nameInputs[index];var rawName=nameInput.getRawName();var selectedLetter=nameInput.getSelectedLetter().toUpperCase();var isActive=index===this.m_currentPlayer;var text=isActive?"> ":"  ";var i=0;var letter=" ";text+="PLAYER "+(index+1)+": ";for(i=0;i<4;i++){letter=rawName.charAt(i);if(!letter&&isActive&&i===rawName.length&&!nameInput.isComplete())letter=selectedLetter;if(!letter)letter=" ";text+="["+letter+
"] "}return text};runmysteriet.scene.TextInputView.prototype.areBothNamesComplete=function(){return this.m_nameInputs[0].isComplete()&&this.m_nameInputs[1].isComplete()};runmysteriet.scene.TextInputView.prototype.startGame=function(){var player1Name=this.m_nameInputs[0].getName();var player2Name=this.m_nameInputs[1].getName();var highscoreName=player1Name+"/"+player2Name;this.application.scenes.load([new runmysteriet.scene.Game(1,0,highscoreName)])};
